-- A stored skeleton past one row (t1583). D1 holds at most 2,000,000 bytes in a row, so a skeleton longer than `SKELETON_ROW_BYTES` keeps its first piece in `deposits.skeleton` and the rest here, in order from piece 1; a skeleton that fits keeps no row here, so every row stored before this reads as it did.
-- The pieces are written and replaced in the deposit's own transaction under its `ingest` mark, and an erasure deletes them with the content. They are not the ledger row (that stays in `deposits`), so they may be deleted; a renamed deposit (an erased account's `unlink`) carries its pieces with it.
CREATE TABLE deposit_skeleton_rows (account TEXT NOT NULL, id TEXT NOT NULL, piece INTEGER NOT NULL CHECK (piece >= 1), body TEXT NOT NULL, PRIMARY KEY (account, id, piece), FOREIGN KEY (account, id) REFERENCES deposits (account, id) ON UPDATE CASCADE) STRICT;
